<?php require_once __DIR__.'/../config/auth.php';require_login();$s=db()->prepare('SELECT e.*,l.titulo,l.autor FROM emprestimos e JOIN livros l ON l.id=e.livro_id WHERE e.usuario_id=? AND e.status="devolvido" ORDER BY e.data_devolucao DESC');$s->execute([user()['id']]);$loans=$s->fetchAll();$pageTitle='Histórico';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><section class="panel"><div class="table-wrap"><table><thead><tr><th>Livro</th><th>Empréstimo</th><th>Devolvido em</th></tr></thead><tbody><?php foreach($loans as $l):?><tr><td><b><?=e($l['titulo'])?></b><br><small><?=e($l['autor'])?></small></td><td><?=date('d/m/Y',strtotime($l['data_emprestimo']))?></td><td><?=date('d/m/Y',strtotime($l['data_devolucao']))?></td></tr><?php endforeach;?><?php if(!$loans):?><tr><td colspan="3" class="empty">Seu histórico estará disponível após a primeira devolução.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
